func (s spanDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*model.Span, err error) {
	buf := make([]*model.Span, 0, batchSize)
	err = s.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

